'use client'

import { useState, useMemo, useEffect } from 'react'
import { STORY_SCENARIOS } from '@/utils/scenarios'
import { backgroundStoryAction } from '@/app/actions/backgroundStoryAction'
import { Sparkles, CheckCircle, XCircle, Play, Loader2, Globe, Search, Filter, Database, Zap } from 'lucide-react'
import { createClient } from '@/utils/supabase/client'

export default function ScenarioDashboard({ cachedJobs }: { cachedJobs: any[] }) {
    const [filter, setFilter] = useState<'all' | 'tr' | 'en'>('all')
    const [statusFilter, setStatusFilter] = useState<'all' | 'ready' | 'missing'>('all')
    const [isGeneratingAll, setIsGeneratingAll] = useState(false)
    const [processingIndex, setProcessingIndex] = useState<number | null>(null)
    const [localCachedThemes, setLocalCachedThemes] = useState<string[]>(
        cachedJobs?.map(job => job.payload?.theme).filter(Boolean) || []
    )
    const [searchTerm, setSearchTerm] = useState('')

    const supabase = createClient()

    const scenarios = useMemo(() => {
        return STORY_SCENARIOS.map((s, index) => {
            const langPrefix = s.language === 'en' ? 'English' : 'Turkish'
            const chars = s.characters.join(', ')
            // StoryForm.tsx'deki aynı formatta tema metni oluşturuyoruz (Mühür/Cache Key)
            const theme = `${langPrefix} dilinde. ${s.genre} tarzında. Konu: ${s.prompt}. Çizim Stili: ${s.style}. Ses Seçimi: ${s.voice}. Karakterler: ${chars}.`
            return { ...s, theme, isReady: localCachedThemes.includes(theme), originalIndex: index }
        })
    }, [localCachedThemes])

    const filteredScenarios = scenarios.filter(s => {
        const langMatch = filter === 'all' || s.language === filter
        const statusMatch = statusFilter === 'all' || (statusFilter === 'ready' ? s.isReady : !s.isReady)
        const searchMatch = s.prompt.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           s.characters.join(' ').toLowerCase().includes(searchTerm.toLowerCase())
        return langMatch && statusMatch && searchMatch
    })

    const waitForJob = async (jobId: string) => {
        return new Promise((resolve) => {
            const interval = setInterval(async () => {
                const { data } = await supabase.from('generation_jobs').select('status').eq('id', jobId).single()
                if (data?.status === 'completed' || data?.status === 'failed') {
                    clearInterval(interval)
                    resolve(data.status)
                }
            }, 3000)
        })
    }

    const generateScenario = async (scenario: any, index: number) => {
        setProcessingIndex(index)
        try {
            const res = await backgroundStoryAction({
                hero: scenario.characters.join(', '),
                theme: scenario.theme,
                voiceOption: 'AI',
                childName: 'Kullanıcı',
                age: scenario.age,
                style: scenario.style,
                elevenVoiceId: scenario.voice,
                isShuffle: true,
                language: scenario.language
            })

            if (res.success && res.jobId) {
                const status = await waitForJob(res.jobId)
                if (status === 'completed') {
                    setLocalCachedThemes(prev => [...prev, scenario.theme])
                }
            }
        } catch (err) {
            console.error(err)
        } finally {
            setProcessingIndex(null)
        }
    }

    const fillMissing = async () => {
        if (!confirm('Tüm eksik taslaklar sırayla üretilecektir. Bu işlem zaman alabilir ve API kredilerinizi kullanır. Onaylıyor musunuz?')) return
        
        setIsGeneratingAll(true)
        const missing = filteredScenarios.filter(s => !s.isReady)
        
        for (const s of missing) {
            await generateScenario(s, s.originalIndex)
        }
        setIsGeneratingAll(false)
    }

    const readyCount = scenarios.filter(s => s.isReady).length
    const totalCount = scenarios.length
    const percent = Math.round((readyCount / totalCount) * 100)

    return (
        <div className="bg-white rounded-[2.5rem] shadow-sm border border-sky-100 overflow-hidden mt-12 animate-in fade-in slide-in-from-bottom-10 duration-1000">
            <div className="p-8 border-b border-sky-50 flex flex-col md:flex-row md:items-center justify-between bg-sky-50/30 gap-6">
                <div>
                    <h2 className="text-2xl font-black text-gray-900 flex items-center gap-3 font-lora">
                        <Database className="text-sky-500" />
                        Sihirli Taslaklar (Cache) Yönetimi
                    </h2>
                    <p className="text-gray-500 text-sm font-medium mt-1">Kütüphanedeki hazır masalların doluluk oranını ve durumunu yönetin.</p>
                </div>
                
                <div className="flex items-center gap-3">
                    <div className="flex flex-col items-end">
                        <span className="text-[10px] font-black text-sky-600 uppercase tracking-widest mb-1">Doluluk Oranı</span>
                        <div className="flex items-center gap-3">
                            <div className="w-32 h-2 bg-gray-200 rounded-full overflow-hidden">
                                <div className="h-full bg-sky-500 transition-all duration-1000" style={{ width: `${percent}%` }} />
                            </div>
                            <span className="text-sm font-black text-gray-900">%{percent}</span>
                        </div>
                    </div>
                    <button 
                        onClick={fillMissing}
                        disabled={isGeneratingAll || readyCount === totalCount}
                        className="ml-4 px-6 py-3 bg-gray-900 text-white rounded-2xl font-bold text-sm flex items-center gap-2 hover:bg-black transition-all shadow-lg shadow-gray-200 disabled:opacity-50 disabled:cursor-not-allowed active:scale-95"
                    >
                        {isGeneratingAll ? <Loader2 className="animate-spin" size={18} /> : <Zap size={18} className="text-yellow-400" />}
                        Eksikleri Doldur
                    </button>
                </div>
            </div>

            {/* Filtreler */}
            <div className="p-6 border-b border-gray-50 flex flex-wrap items-center gap-4 bg-white">
                <div className="relative flex-1 min-w-[200px]">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Taslaklarda ara..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-2xl text-sm focus:outline-none focus:border-sky-300 transition-all"
                    />
                </div>
                
                <div className="flex items-center gap-2 bg-gray-50 p-1.5 rounded-2xl border border-gray-100">
                    <button onClick={() => setFilter('all')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${filter === 'all' ? 'bg-white text-sky-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>HEPSİ</button>
                    <button onClick={() => setFilter('tr')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all flex items-center gap-2 ${filter === 'tr' ? 'bg-white text-sky-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>
                        <Globe size={14} /> TR
                    </button>
                    <button onClick={() => setFilter('en')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all flex items-center gap-2 ${filter === 'en' ? 'bg-white text-sky-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>
                        <Globe size={14} /> EN
                    </button>
                </div>

                <div className="flex items-center gap-2 bg-gray-50 p-1.5 rounded-2xl border border-gray-100">
                    <button onClick={() => setStatusFilter('all')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${statusFilter === 'all' ? 'bg-white text-gray-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>TÜMÜ</button>
                    <button onClick={() => setStatusFilter('ready')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all flex items-center gap-2 ${statusFilter === 'ready' ? 'bg-white text-emerald-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>
                        <CheckCircle size={14} /> HAZIR
                    </button>
                    <button onClick={() => setStatusFilter('missing')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all flex items-center gap-2 ${statusFilter === 'missing' ? 'bg-white text-red-500 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>
                        <XCircle size={14} /> EKSİK
                    </button>
                </div>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50/30 text-gray-400 text-[10px] font-black uppercase tracking-widest">
                            <th className="px-8 py-4">Dil</th>
                            <th className="px-8 py-4">Karakterler</th>
                            <th className="px-8 py-4">Konu Özeti</th>
                            <th className="px-8 py-4">Durum</th>
                            <th className="px-8 py-4 text-right">İşlem</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {filteredScenarios.map((s) => (
                            <tr key={s.theme} className="hover:bg-gray-50/30 transition group">
                                <td className="px-8 py-5">
                                    <span className={`px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider ${s.language === 'en' ? 'bg-indigo-50 text-indigo-600 border border-indigo-100' : 'bg-red-50 text-red-600 border border-red-100'}`}>
                                        {s.language}
                                    </span>
                                </td>
                                <td className="px-8 py-5">
                                    <p className="text-xs font-bold text-gray-900">{s.characters.join(', ')}</p>
                                    <p className="text-[10px] text-gray-400 mt-0.5">{s.genre} • {s.style}</p>
                                </td>
                                <td className="px-8 py-5">
                                    <p className="text-sm text-gray-600 font-medium line-clamp-1 max-w-md">{s.prompt}</p>
                                </td>
                                <td className="px-8 py-5">
                                    {s.isReady ? (
                                        <div className="flex items-center gap-2 text-emerald-600">
                                            <CheckCircle size={16} />
                                            <span className="text-[10px] font-black uppercase tracking-widest">Hazır</span>
                                        </div>
                                    ) : (
                                        <div className="flex items-center gap-2 text-red-400">
                                            <XCircle size={16} />
                                            <span className="text-[10px] font-black uppercase tracking-widest">Üretilmedi</span>
                                        </div>
                                    )}
                                </td>
                                <td className="px-8 py-5 text-right">
                                    {!s.isReady && (
                                        <button 
                                            onClick={() => generateScenario(s, s.originalIndex)}
                                            disabled={processingIndex === s.originalIndex || isGeneratingAll}
                                            className="p-2 bg-gray-100 text-gray-400 rounded-xl hover:bg-sky-500 hover:text-white transition-all shadow-sm active:scale-90 disabled:opacity-50"
                                            title="Şimdi Üret"
                                        >
                                            {processingIndex === s.originalIndex ? (
                                                <Loader2 size={16} className="animate-spin" />
                                            ) : (
                                                <Play size={16} />
                                            )}
                                        </button>
                                    )}
                                    {s.isReady && (
                                        <div className="p-2 text-emerald-500">
                                            <Sparkles size={16} />
                                        </div>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    )
}
